BEGIN
 FOR r IN SELECT value FROM jsonb_array_elements($previews$[{"ok":true,"quick":{"version":"QUICK_SCREEN_20261030_1","ai_calls":1,"pages_read":34,"text_chars":44947,"first_seen_at":"2026-10-30T16:18:12.025Z","last_ai_pages":34},"action":"DECIDE","reason":"NO_GO — quick screen: TURNOVER_ABOVE_COMPANY_LIMIT. The tender is an EOI for development support and product development of a smart health band wearable plus command & control system. Although it contains substantial custom software/application development, the mandatory pre-qualification requires a minimum annual turnover of Rs.5 Crore in each of the last three financial years, which exceeds the Rs.3 Crore ceiling. The EOI does not permit a consortium/JV to satisfy the turnover (it only allows tie-ups for technical capability, not for the financial eligibility), so the hard turnover rule applies and the tender is NO_GO. EMD is Nil (0.00), so the EMD rule is not triggered. Evidence: \"The applicant shall have a minimum annual turnover of ₹5 Crore (Rupees Five Crore) or\nabove in each of the last three financial years.\" | \"The applicant shall have a minimum annual turnover of ₹5 Crore (Rupees Five Crore) or\nabove in each of the last three financial years.\"","decision":"NO_GO","tender_id":"d7ea3972-5654-48c6-b9dc-e828a3fc3409","assessment":{"model":"deepseek-flash","usage":{"total_tokens":14742,"prompt_tokens":14154,"completion_tokens":588,"prompt_tokens_details":{"cached_tokens":5632},"prompt_cache_hit_tokens":5632,"prompt_cache_miss_tokens":8522},"reason":"The tender is an EOI for development support and product development of a smart health band wearable plus command & control system. Although it contains substantial custom software/application development, the mandatory pre-qualification requires a minimum annual turnover of Rs.5 Crore in each of the last three financial years, which exceeds the Rs.3 Crore ceiling. The EOI does not permit a consortium/JV to satisfy the turnover (it only allows tie-ups for technical capability, not for the financial eligibility), so the hard turnover rule applies and the tender is NO_GO. EMD is Nil (0.00), so the EMD rule is not triggered.","missing":null,"sources":[{"ref":"L","kind":"LISTING","name":"Tender listing"},{"ref":"K","kind":"DOCUMENT","name":"Key clauses (turnover / EMD / net worth / JV / OEM / limited tender) from all documents","coverage":"all documents searched"},{"ref":"D1","kind":"DOCUMENT","name":"tendernotice-1.pdf","coverage":"complete document","document_id":"2502521b-eb62-4054-9743-99d4abfe91ac"},{"ref":"D2","kind":"DOCUMENT","name":"8b2f73c8-9328-4be6-b1e1-4318b1981adc.html","coverage":"complete document","document_id":"49a2b212-50e3-4003-9ade-e1758d870550"}],"decision":"NO_GO","evidence":[{"ref":"K","quote":"The applicant shall have a minimum annual turnover of ₹5 Crore (Rupees Five Crore) or\nabove in each of the last three financial years.","rule_code":"TURNOVER_ABOVE_COMPANY_LIMIT"},{"ref":"D1","quote":"The applicant shall have a minimum annual turnover of ₹5 Crore (Rupees Five Crore) or\nabove in each of the last three financial years.","rule_code":"TURNOVER_ABOVE_COMPANY_LIMIT"},{"ref":"D1","quote":"The applicant shall possess the technical capability and resources required for the proposed\ndevelopment work, either independently or through tie-ups or collaborations with suitable\ntechnology providers, hardware manufacturers, software developers or other relevant\norganizations.","rule_code":null}],"rule_code":"TURNOVER_ABOVE_COMPANY_LIMIT","pages_read":34,"review_notes":["Turnover requirement of Rs.5 Crore per year for each of the last three years exceeds the Rs.3 Crore ceiling; tie-ups/collaborations are permitted only for technical capability, not for the financial eligibility, so consortium/JV does not cure the turnover failure.","Scope also includes substantial hardware/wearable device product development (smart health band, firmware, sensors, contract manufacturing/sourcing), which leans toward the HARDWARE exclusion, but the turnover rule is the decisive hard failure.","Registered office in Kerala is a mandatory eligibility condition (18.2) that would also need verification."],"emd_exemption":"EMD Amount is 0.00 (Nil); EMD Exemption Allowed: No","primary_scope":"Development support, application development and product development for an elderly care smart health band (wearable hardware) and integrated command & control system, including mobile apps, backend, APIs and hardware/firmware development.","quick_version":"QUICK_SCREEN_20261030_1","still_reading":false,"emd_payable_inr":0,"consortium_allowed":false,"validation_problems":[],"turnover_required_inr":50000000},"quick_version":"QUICK_SCREEN_20261030_1","current_status":"CONDITIONAL_GO","changed_business_statuses":0},{"ok":true,"quick":{"version":"QUICK_SCREEN_20261030_1","ai_calls":1,"pages_read":33,"text_chars":59604,"first_seen_at":"2026-10-30T16:18:12.018Z","last_ai_pages":33},"action":"DECIDE","reason":"NO_GO — quick screen: OEM_AUTH_REQUIRED. The primary deliverable is new custom software development (a software module in an existing portal), which would otherwise be a software fit. However, the tender imposes a mandatory OEM/Authorised Integrator requirement with a Tender-specific Manufacturer Authorization (MAF) letter for major active and passive items in the BOQ, and EMD exemption is explicitly disallowed. The mandatory OEM authorization requirement triggers the OEM_AUTH_REQUIRED hard NO_GO rule. EMD of INR 2,900 is below the INR 5,00,000 limit and turnover is not stated as a mandatory average annual turnover above INR 3 crore, so those financial rules do not independently fail; the OEM authorization requirement is the operative exclusion. Evidence: \"Bidder must be OEM/Authorised Integrator of the OEM and Tender specific Authorization letter (MAF), for major active and passive items in the BOQ, to be enclosed in specified format given in annexture-I, which is to be g\" | \"Bidder must be OEM/Authorised Integrator of the OEM and Tender specific Authorization letter (MAF), for major active and passive items in the BOQ, to be enclosed in specified format given in annexture-I, which is to be g\"","decision":"NO_GO","tender_id":"1d078260-9a1a-4851-901b-5fbf79096ad1","assessment":{"model":"deepseek-flash","usage":{"total_tokens":13546,"prompt_tokens":12900,"completion_tokens":646,"prompt_tokens_details":{"cached_tokens":5760},"prompt_cache_hit_tokens":5760,"prompt_cache_miss_tokens":7140},"reason":"The primary deliverable is new custom software development (a software module in an existing portal), which would otherwise be a software fit. However, the tender imposes a mandatory OEM/Authorised Integrator requirement with a Tender-specific Manufacturer Authorization (MAF) letter for major active and passive items in the BOQ, and EMD exemption is explicitly disallowed. The mandatory OEM authorization requirement triggers the OEM_AUTH_REQUIRED hard NO_GO rule. EMD of INR 2,900 is below the INR 5,00,000 limit and turnover is not stated as a mandatory average annual turnover above INR 3 crore, so those financial rules do not independently fail; the OEM authorization requirement is the operative exclusion.","missing":null,"sources":[{"ref":"L","kind":"LISTING","name":"Tender listing"},{"ref":"K","kind":"DOCUMENT","name":"Key clauses (turnover / EMD / net worth / JV / OEM / limited tender) from all documents","coverage":"all documents searched"},{"ref":"D1","kind":"DOCUMENT","name":"enit221t.pdf","coverage":"complete document","document_id":"3f0bcf37-b7ca-485f-ad1c-9cd9acd9c112"},{"ref":"D2","kind":"DOCUMENT","name":"3afb4033-9410-4bf2-b7c8-995fc3609314.html","coverage":"complete document","document_id":"643fced7-3078-424b-b9fc-aab9f904b871"}],"decision":"NO_GO","evidence":[{"ref":"K","quote":"Bidder must be OEM/Authorised Integrator of the OEM and Tender specific Authorization letter (MAF), for major active and passive items in the BOQ, to be enclosed in specified format given in annexture-I, which is to be given latest before supply of Items/materials.","rule_code":"OEM_AUTH_REQUIRED"},{"ref":"D1","quote":"Bidder must be OEM/Authorised Integrator of the OEM and Tender specific Authorization letter (MAF), for major active and passive items in the BOQ, to be enclosed in specified format given in annexture-I, which is to be given latest before supply of Items/materials.","rule_code":"OEM_AUTH_REQUIRED"},{"ref":"K","quote":"Submission of EMD is mandatory for each and every bidder. No exemption is allowed.","rule_code":"EMD_LIMIT"},{"ref":"D1","quote":"Earnest Money : The amount of Earnest Money Rupees 2900.00 Through e-procurement portal of state Govt.","rule_code":"EMD_LIMIT"}],"rule_code":"OEM_AUTH_REQUIRED","pages_read":33,"review_notes":["Scope is a genuine custom software module development in an existing PWD portal, which is a positive software fit.","Mandatory OEM/Authorised Integrator MAF requirement for major active and passive BOQ items is the operative hard exclusion (OEM_AUTH_REQUIRED).","JV/consortium is explicitly disallowed ('Not a member of joint venture or sub contractor').","EMD of INR 2,900 is well below the INR 5,00,000 limit; no EMD-based exclusion.","No mandatory average annual turnover above INR 3 crore clause was found in the supplied text."],"emd_exemption":"No exemption allowed per clause xxiii; EMD of INR 2,900 payable via e-procurement portal.","primary_scope":"Development, customization and implementation of a new dedicated software module in the PWD Road-Cutting Permission Portal to assist Bharatnet project implementation (Job No. KIT/OW/193 of 26-27).","quick_version":"QUICK_SCREEN_20261030_1","still_reading":false,"emd_payable_inr":2900,"consortium_allowed":false,"validation_problems":[],"turnover_required_inr":null},"quick_version":"QUICK_SCREEN_20261030_1","current_status":"CONDITIONAL_GO","changed_business_statuses":0},{"ok":true,"quick":{"version":"QUICK_SCREEN_20261030_1","ai_calls":1,"pages_read":62,"text_chars":149229,"first_seen_at":"2026-10-30T16:18:16.524Z","last_ai_pages":62},"action":"DECIDE","reason":"NO_GO — quick screen: TURNOVER_ABOVE_COMPANY_LIMIT. The primary deliverable is new custom software implementation (OBPAS), which would otherwise be a software fit. However, the RFP mandates an average annual turnover of Rs. 5 Crores over the last 3 audited financial years, which exceeds the INR 3 crore ceiling, and the tender explicitly states that Joint Venture / Consortium is NOT allowed. With no consortium route available, the mandatory turnover above the company limit is a hard NO_GO under TURNOVER_ABOVE_COMPANY_LIMIT. Evidence: \"The Bidder should have an average annual turnover\nof Rs. 05 Crores in last 3 audited financial years\n(2022-23, 2023-24 & 2024-25).\" | \"Consortium / Joint Venture (JV) is not allowed.\"","decision":"NO_GO","tender_id":"f548b36f-7131-466f-b324-2a2c50b861cc","assessment":{"model":"deepseek-flash","usage":{"total_tokens":16492,"prompt_tokens":16016,"completion_tokens":476,"prompt_tokens_details":{"cached_tokens":5504},"prompt_cache_hit_tokens":5504,"prompt_cache_miss_tokens":10512},"reason":"The primary deliverable is new custom software implementation (OBPAS), which would otherwise be a software fit. However, the RFP mandates an average annual turnover of Rs. 5 Crores over the last 3 audited financial years, which exceeds the INR 3 crore ceiling, and the tender explicitly states that Joint Venture / Consortium is NOT allowed. With no consortium route available, the mandatory turnover above the company limit is a hard NO_GO under TURNOVER_ABOVE_COMPANY_LIMIT.","missing":null,"sources":[{"ref":"L","kind":"LISTING","name":"Tender listing"},{"ref":"K","kind":"DOCUMENT","name":"Key clauses (turnover / EMD / net worth / JV / OEM / limited tender) from all documents","coverage":"all documents searched"},{"ref":"D1","kind":"DOCUMENT","name":"963324e4-d8ba-4372-b8e3-bc3f92d65e7b-rfp-obpas-bda-final-v2.pdf","coverage":"complete document","document_id":"8432d04c-4bc8-4c8b-906b-93e1fa063167"},{"ref":"D2","kind":"DOCUMENT","name":"boq-details.pdf","coverage":"complete document","document_id":"67b2f476-80e2-4982-a0af-e21b88cb1a1b"},{"ref":"D3","kind":"DOCUMENT","name":"2308b69c-5bd7-4a5a-9695-5dab869c9795.html","coverage":"complete document","document_id":"b87d99ef-141e-44fa-8da1-4fba9511b212"}],"decision":"NO_GO","evidence":[{"ref":"K","quote":"The Bidder should have an average annual turnover\nof Rs. 05 Crores in last 3 audited financial years\n(2022-23, 2023-24 & 2024-25).","rule_code":"TURNOVER_ABOVE_COMPANY_LIMIT"},{"ref":"K","quote":"Consortium / Joint Venture (JV) is not allowed.","rule_code":"TURNOVER_ABOVE_COMPANY_LIMIT"},{"ref":"K","quote":"13.\tConsortium\tJoint Venture / Consortium – Not allowed","rule_code":"TURNOVER_ABOVE_COMPANY_LIMIT"}],"rule_code":"TURNOVER_ABOVE_COMPANY_LIMIT","pages_read":62,"review_notes":["EMD is INR 125,000 (2.5% of estimated amount per Data Sheet; listing shows 125000), which is within the INR 5,00,000 limit — EMD is not a disqualifier.","Scope is a genuine custom software implementation (OBPAS) with O&M, which would be a software fit; the disqualifier is purely the turnover threshold combined with the no-consortium clause.","Mandatory certifications ISO 9001:2015 and ISO/IEC 27001:2022 and 5-year existence requirement also apply but were not the deciding factor."],"emd_exemption":null,"primary_scope":"Configuration, Installation, Integration, Commissioning and O&M of an Online Building Plan Approval System (OBPAS) for BDA — a custom software implementation project.","quick_version":"QUICK_SCREEN_20261030_1","still_reading":false,"emd_payable_inr":125000,"consortium_allowed":false,"validation_problems":[],"turnover_required_inr":50000000},"quick_version":"QUICK_SCREEN_20261030_1","current_status":"CONDITIONAL_GO","changed_business_statuses":0}]$previews$::jsonb)
 LOOP
  IF r->>'decision'<>'NO_GO' OR coalesce((r#>>'{assessment,pages_read}')::integer,0)<=0
   THEN RAISE EXCEPTION 'Invalid correction evidence'; END IF;
  SELECT * INTO t FROM public.agenttender_tenders WHERE id=(r->>'tender_id')::uuid FOR UPDATE;
  IF NOT FOUND OR t.source_region IS DISTINCT FROM 'INDIAN' OR t.qualification_status IS DISTINCT FROM 'CONDITIONAL_GO'
    OR coalesce(lower(t.decision_source),'') LIKE '%manual%'
    OR upper(coalesce(t.status,'')) IN ('GO','SUBMITTED','WON','WILL_BID','WILL-BID','UNDER_EVALUATION')
    OR EXISTS(SELECT 1 FROM public.agenttender_bid_workspaces w WHERE w.tender_id=t.id)
  THEN CONTINUE; END IF;
  UPDATE public.agenttender_tenders SET qualification_status='NO_GO',status='NO_BID',prescreen_status='REJECTED',
    decision_source='ORCHESTRATOR_V2',prescreen_reason=left(r->>'reason',1000),prescreened_at=now(),updated_at=now()
  WHERE id=t.id RETURNING qualification_status INTO actual;
  IF actual IS DISTINCT FROM 'NO_GO' THEN RAISE EXCEPTION 'DECISION_TRIGGER_CONFLICT: %',t.id; END IF;
  INSERT INTO public.agenttender_v2_decision_audit(tender_id,final_decision,matched_rule_codes,rule_versions,evidence,worker_version,model,decision_source,reason,assessment)
  VALUES(t.id,'NO_GO',jsonb_build_array(r#>>'{assessment,rule_code}'),'{}'::jsonb,
    coalesce(r#>'{assessment,evidence}','[]'::jsonb),r->>'quick_version',r#>>'{assessment,model}','ORCHESTRATOR_V2',left(r->>'reason',1000),
    (r->'assessment')||jsonb_build_object('quick',r->'quick','correction','CONDITIONAL_GO_READABLE_DOCUMENT_RECHECK_20261030','previous_qualification_status',t.qualification_status,'previous_prescreen_reason',t.prescreen_reason));
  INSERT INTO public.agenttender_orch_v2_events(tender_id,step,event_type,details)
  VALUES(t.id,3,'QUICK_SCREEN_DECISION_COMMITTED',jsonb_build_object('decision','NO_GO','correction',true,'reason',left(r->>'reason',1000),'rule_code',r#>>'{assessment,rule_code}','pages_read',r#>'{assessment,pages_read}'));
 END LOOP;
END
